/* Loads giscus comments and reactions; generated by the blog build. */
(() => {
  const host = document.getElementById("comments");
  if (!host) return;
  const root = document.documentElement;
  const dark = matchMedia("(prefers-color-scheme: dark)");
  const theme = () => {
    const chosen = root.dataset.theme;
    return chosen === "dark" || chosen === "light" ? chosen : dark.matches ? "dark" : "light";
  };
  const d = host.dataset;
  const attributes = {
    "data-repo": d.giscusRepo, "data-repo-id": d.giscusRepoId,
    "data-category": d.giscusCategory, "data-category-id": d.giscusCategoryId,
    "data-mapping": d.giscusMapping, "data-strict": "0",
    "data-reactions-enabled": d.giscusReactions, "data-emit-metadata": "0",
    "data-input-position": "top", "data-theme": theme(), "data-lang": d.giscusLang, "data-loading": "lazy",
  };
  const script = document.createElement("script");
  script.src = "https://giscus.app/client.js";
  script.async = true;
  script.crossOrigin = "anonymous";
  for (const [name, value] of Object.entries(attributes)) if (value) script.setAttribute(name, value);
  host.appendChild(script);
  const sync = () => document.querySelector("iframe.giscus-frame")?.contentWindow
    ?.postMessage({ giscus: { setConfig: { theme: theme() } } }, "https://giscus.app");
  new MutationObserver(sync).observe(root, { attributes: true, attributeFilter: ["data-theme"] });
  dark.addEventListener?.("change", sync);
})();
